 * Types for the Qwen Code CLI transcript integration.
 *
 * Qwen Code records each coding-agent session as a JSONL transcript where every
 * line is a {@link ChatRecord}. Records use a Gemini-style message shape: a
 * message has a `role` and an array of {@link GeminiPart} objects (text,
 * functionCall, or functionResponse parts).
 */

/**
 * A text part. `thought` marks reasoning/thinking text that should be excluded
 * from user-facing content by default.
 */
export interface TextPart {
  text: string;
  thought?: boolean;
}

/**
 * A function-call part emitted by the model when invoking a tool.
 */
export interface FunctionCallPart {
  functionCall: {
    id: string;
    name: string;
    args?: Record<string, any>;
  };
}

/**
 * A function-response part carrying the result of a tool invocation.
 */
export interface FunctionResponsePart {
  functionResponse: {
    id: string;
    name: string;
    response: any;
  };
}

/**
 * Union of the message part shapes used in Gemini-style messages.
 */
export type GeminiPart = TextPart | FunctionCallPart | FunctionResponsePart;

/**
 * A structured message with a role and an array of parts.
 */
export interface GeminiMessage {
  role: string;
  parts: GeminiPart[];
}

/**
 * Token usage metadata attached to assistant records.
 */
export interface UsageMetadata {
  promptTokenCount: number;
  candidatesTokenCount: number;
  totalTokenCount: number;
}

/**
 * The result of a tool call, attached to `tool_result` records.
 */
export interface ToolCallResult {
  callId: string;
  status: string;
  resultDisplay?: any;
}

/**
 * A single record (one JSONL line) in a Qwen Code conversation transcript.
 */
export interface ChatRecord {
  uuid: string;
  parentUuid: string | null;
  sessionId: string;
  timestamp: string;
  type: 'user' | 'assistant' | 'system' | 'tool_result';
  message?: GeminiMessage | string;
  toolCallResult?: ToolCallResult;
  usageMetadata?: UsageMetadata;
  model?: string;
}

/**
 * OpenAI chat-format tool call, used on assistant messages.
 */
export interface OpenAIToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
}

/**
 * OpenAI chat-format message used in LLM span inputs. Matches the message
 * structure the MLflow UI Chat view renders.
 */
export interface OpenAIMessage {
  role: 'user' | 'assistant' | 'system' | 'tool';
  content: string | null;
  tool_calls?: OpenAIToolCall[];
  tool_call_id?: string;
}
