FunctionResponsePart(part: GeminiPart): part is FunctionResponsePart {\n  return typeof part === 'object' && part !== null && 'functionResponse' in part;\n}\n\n/**\n * Extract text content from a record's message.\n *\n * Joins all text parts with a newline. Excludes parts where `thought` is true\n * unless `includeThoughts` is true. Plain string messages are returned as-is.\n * functionCall and functionResponse parts contribute no text.\n */\nexport function getMessageText(record: ChatRecord, includeThoughts = false): string {\n  const message = record.message;\n  if (!message) {\n    return '';\n  }\n  if (typeof message === 'string') {\n    return message;\n  }\n  const parts = message.parts;\n  if (!Array.isArray(parts)) {\n    return '';\n  }\n  return parts\n    .filter(isTextPart)\n    .filter((part) => includeThoughts || !part.thought)\n    .map((part) => part.text)\n    .join('\\n');\n}\n\n/**\n * Extract all functionCall parts from a record's message.\n * Returns an empty array for records with no message or no functionCall parts.\n */\nexport function getFunctionCalls(\n  record: ChatRecord,\n): Array<{ id: string; name: string; args?: Record<string, any> }> {\n  const message = record.message;\n  if (!message || typeof message === 'string') {\n    return [];\n  }\n  const parts = message.parts;\n  if (!Array.isArray(parts)) {\n    return [];\n  }\n  return parts.filter(isFunctionCallPart).map((part) => ({\n    id: part.functionCall.id,\n    name: part.functionCall.name,\n    args: part.functionCall.args,\n  }));\n}\n\n/**\n * Build a Map from tool call id to the tool_result record producing it.\n * Non-tool_result records are excluded.\n */\nexport function buildToolResultMap(records: ChatRecord[]): Map<string, ChatRecord> {\n  const map = new Map<string, ChatRecord>();\n  for (const record of records) {\n    if (record.type === 'tool_result' && record.toolCallResult?.callId) {\n      map.set(record.toolCallResult.callId, record);\n    }\n  }\n  return map;\n}\n\n/**\n * Normalize a resultDisplay value to a string. String values pass through\n * unchanged, objects are JSON.stringified, null/undefined become an empty\n * string.\n */\nexport function formatResultDisplay(display: any): string {\n  if (display === null || display === undefined) {\n    return '';\n  }\n  if (typeof display === 'string') {\n    return display;\n  }\n  return JSON.stringify(display);\n}\n\n/**\n * Extract tool output from a tool_result record.\n *\n * Prefers `toolCallResult.resultDisplay` (passed through formatResultDisplay).\n * Falls back to JSON.stringify of the functionResponse.response found in the\n * message parts when resultDisplay is absent. Returns an empty string when\n * neither is available.\n */\nexport function getToolOutput(record: ChatRecord): string {\n  const resultDisplay = record.toolCallResult?.resultDisplay;\n  if (resultDisplay !== null && resultDisplay !== undefined) {\n    return formatResultDisplay(resultDisplay);\n  }\n\n  const message = record.message;\n  if (message && typeof message !== 'string' && Array.isArray(message.parts)) {\n    for (const part of message.parts) {\n      if (isFunctionResponsePart(part)) {\n        return JSON.stringify(part.functionResponse.response);\n      }\n    }\n  }\n  return '';\n}\n\n/**\n * Return the records belonging to the last turn: a slice starting at the last\n * record whose type is 'user' and continuing to the end. When no user record\n * exists, the full array is returned.\n */\nexport function getLastTurnRecords(records: ChatRecord[]): ChatRecord[] {\n  for (let i = records.length - 1; i >= 0; i--) {\n    if (records[i].type === 'user') {\n      return records.slice(i);\n    }\n  }\n  return records.slice(0);\n}\n\n/**\n * Map a usageMetadata object to token-usage counts.\n * Returns null when the argument is undefined or missing.\n */\nexport function getTokenUsage(\n  usageMetadata: any,\n): { input: number; output: number; total: number } | null {\n  if (!usageMetadata) {\n    return null;\n  }\n  return {\n    input: usageMetadata.promptTokenCount,\n    output: usageMetadata.candidatesTokenCount,\n    total: usageMetadata.totalTokenCount,\n  };\n}\n"],"version":3}
