rent ? options.parent.spanId : null;\n    const span: any = {\n      name: options.name,\n      traceId: 'mock-trace-id',\n      spanId: id,\n      parentId,\n      spanType: options.spanType ?? 'UNKNOWN',\n      inputs: options.inputs ?? {},\n      outputs: {},\n      attributes: { ...(options.attributes ?? {}) },\n      startTimeNs: options.startTimeNs ?? null,\n      endTimeNs: null,\n      statusCode: null,\n      statusMessage: null,\n      setAttribute: jest.fn((k: string, v: any) => {\n        span.attributes[k] = v;\n      }),\n      setStatus: jest.fn((code: string, message?: string) => {\n        span.statusCode = code;\n        span.statusMessage = message ?? null;\n      }),\n      end: jest.fn((opts?: any) => {\n        if (opts?.outputs) span.outputs = opts.outputs;\n        if (opts?.endTimeNs != null) span.endTimeNs = opts.endTimeNs;\n      }),\n    };\n    mockSpans[id] = span;\n    return span;\n  }),\n  flushTraces: jest.fn().mockResolvedValue(undefined),\n  SpanStatusCode: { OK: 'STATUS_CODE_OK', ERROR: 'STATUS_CODE_ERROR', UNSET: 'STATUS_CODE_UNSET' },\n  SpanType: { LLM: 'LLM', AGENT: 'AGENT', TOOL: 'TOOL', UNKNOWN: 'UNKNOWN' },\n  SpanAttributeKey: { TOKEN_USAGE: 'mlflow.chat.tokenUsage', MESSAGE_FORMAT: 'mlflow.message.format' },\n  TraceMetadataKey: { TRACE_SESSION: 'mlflow.trace.session', TRACE_USER: 'mlflow.trace.user' },\n  TokenUsageKey: { INPUT_TOKENS: 'input_tokens', OUTPUT_TOKENS: 'output_tokens', TOTAL_TOKENS: 'total_tokens' },\n  InMemoryTraceManager: {\n    getInstance: jest.fn(() => ({ getTrace: jest.fn(() => ({ info: mockTraceInfo })) })),\n  },\n}));\n\nimport { writeFileSync } from 'fs';\nimport { processTranscript, reconstructMessages } from '../src/tracing';\nimport {\n  parseTimestampToNs,\n  getMessageText,\n  getFunctionCalls,\n  isTextPart,\n  isFunctionCallPart,\n  buildToolResultMap,\n  formatResultDisplay,\n  getToolOutput,\n  getLastTurnRecords,\n  getTokenUsage,\n} from '../src/transcript';\nimport { flushTraces } from '@mlflow/core';\nimport type { ChatRecord } from '../src/types';\n\nconst spans = () => Object.values(mockSpans);\nconst byType = (t: string) => spans().filter((s) => s.spanType === t);\nconst root = () => spans().find((s) => s.parentId == null);\n\nconst TS = (s: number) => `2026-04-05T10:00:0${s}Z`;\nconst nsOf = (s: number) => new Date(TS(s)).getTime() * 1_000_000;\n\nfunction transcript(): ChatRecord[] {\n  return [\n    { uuid: 'u1', parentUuid: null, sessionId: 'sess-1', timestamp: TS(0), type: 'user', message: { role: 'user', parts: [{ text: 'list files' }] } },\n    { uuid: 'a1', parentUuid: 'u1', sessionId: 'sess-1', timestamp: TS(1), type: 'assistant', model: 'qwen', message: { role: 'model', parts: [{ text: 'thinking', thought: true }, { text: 'let me look' }, { functionCall: { id: 'c1', name: 'ls', args: { path: '.' } } }] }, usageMetadata: { promptTokenCount: 10, candidatesTokenCount: 5, totalTokenCount: 15 } },\n    { uuid: 't1', parentUuid: 'a1', sessionId: 'sess-1', timestamp: TS(2), type: 'tool_result', toolCallResult: { callId: 'c1', status: 'success', resultDisplay: 'a.txt\\nb.txt' } },\n    { uuid: 'a2', parentUuid: 't1', sessionId: 'sess-1', timestamp: TS(3), type: 'assistant', model: 'qwen', message: { role: 'model', parts: [{ text: 'There are 2 files' }] }, usageMetadata: { promptTokenCount: 20, candidatesTokenCount: 8, totalTokenCount: 28 } },\n  ];\n}\n\nbeforeEach(() => {\n  spanCounter = 0;\n  Object.keys(mockSpans).forEach((k) => delete mockSpans[k]);\n  mockTraceInfo.traceMetadata = {};\n  jest.clearAllMocks();\n});\n\ntest('pure helpers', () => {\n  expect(parseTimestampToNs(null)).toBeNull();\n  expect(parseTimestampToNs('')).toBeNull();\n  expect(parseTimestampToNs(TS(0))).toBe(nsOf(0));\n  const rec = transcript()[1];\n  expect(getMessageText(rec)).toBe('let me look');\n  expect(getMessageText(rec, true)).toBe('thinking\\nlet me look');\n  expect(getMessageText({ ...rec, message: 'plain' })).toBe('plain');\n  expect(getFunctionCalls(rec)).toEqual([{ id: 'c1', name: 'ls', args: { path: '.' } }]);\n  expect(getFunctionCalls({ ...rec, message: undefined })).toEqual([]);\n  expect(isTextPart({ text: 'x' })).toBe(true);\n  expect(isTextPart({ functionCall: { id: '1', name: 'n' } } as any)).toBe(false);\n  expect(isFunctionCallPart({ functionCall: { id: '1', name: 'n' } })).toBe(true);\n  expect(formatResultDisplay('s')).toBe('s');\n  expect(formatResultDisplay({ a: 1 })).toBe('{\"a\":1}');\n  expect(formatResultDisplay(null)).toBe('');\n  expect(formatResultDisplay(undefined)).toBe('');\n  const map = buildToolResultMap(transcript());\n  expect(map.size).toBe(1);\n  expect(map.get('c1')!.uuid).toBe('t1');\n  expect(getToolOutput(transcript()[2])).toBe('a.txt\\nb.txt');\n  expect(getToolOutput({ ...transcript()[2], toolCallResult: { callId: 'c1', status: 'ok' }, message: { role: 'tool', parts: [{ functionResponse: { id: 'c1', name: 'ls', response: { ok: 1 } } }] } })).toBe('{\"ok\":1}');\n  expect(getTokenUsage(undefined)).toBeNull();\n  expect(getTokenUsage({ promptTokenCount: 1, candidatesTokenCount: 2, totalTokenCount: 3 })).toEqual({ input: 1, output: 2, total: 3 });\n  const last = getLastTurnRecords(transcript());\n  expect(last[0].uuid).toBe('u1');\n});\n\ntest('reconstructMessages', () => {\n  const recs = transcript();\n  expect(reconstructMessages(recs, 1)).toEqual([{ role: 'user', content: 'list files' }]);\n  expect(reconstructMessages(recs, 3)).toEqual([\n    { role: 'user', content: 'list files' },\n    { role: 'assistant', content: null, tool_calls: [{ id: 'c1', type: 'function', function: { name: 'ls', arguments: '{\"path\":\".\"}' } }] },\n    { role: 'tool', tool_call_id: 'c1', content: 'a.txt\\nb.txt' },\n  ]);\n});\n\ntest('processTranscript null', async () => {\n  await processTranscript(null);\n  expect(spans().length).toBe(0);\n  expect(flushTraces).not.toHaveBeenCalled();\n});\n\ntest('processTranscript full', async () => {\n  const path = '/tmp/qwen-scratch.jsonl';\n  writeFileSync(path, transcript().map((r) => JSON.stringify(r)).join('\\n'));\n  await processTranscript(path, 'session-xyz');\n\n  const r = root();\n  expect(r.name).toBe('qwen_code_conversation');\n  expect(r.spanType).toBe('AGENT');\n  expect(r.inputs).toBe('list files');\n  expect(r.startTimeNs).toBe(nsOf(0));\n  const endCall = (r.end as jest.Mock).mock.calls[0][0];\n  expect(endCall.outputs).toBe('There are 2 files');\n  expect(r.endTimeNs).toBe(nsOf(3));\n  expect(r.attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 20, output_tokens: 13, total_tokens: 33 });\n\n  const llm = byType('LLM');\n  expect(llm.length).toBe(2);\n  expect(llm[0].startTimeNs).toBe(nsOf(0));\n  expect(llm[0].endTimeNs).toBe(nsOf(1));\n  expect(llm[0].inputs).toEqual({ model: 'qwen', messages: [{ role: 'user', content: 'list files' }] });\n  const llm0end = (llm[0].end as jest.Mock).mock.calls[0][0];\n  expect(llm0end.outputs).toEqual({ choices: [{ message: { role: 'assistant', content: 'let me look' } }] });\n  expect(llm[0].attributes['mlflow.chat.tokenUsage']).toEqual({ input_tokens: 10, output_tokens: 5, total_tokens: 15 });\n  expect(llm[1].startTimeNs).toBe(nsOf(2));\n  expect(llm[1].endTimeNs).toBe(nsOf(3));\n\n  const tool = byType('TOOL');\n  expect(tool.length).toBe(1);\n  expect(tool[0].name).toBe('tool_ls');\n  expect(tool[0].attributes.tool_id).toBe('c1');\n  expect(tool[0].inputs).toEqual({ path: '.' });\n  expect(tool[0].startTimeNs).toBe(nsOf(1));\n  expect(tool[0].endTimeNs).toBe(nsOf(2));\n  const toolEnd = (tool[0].end as jest.Mock).mock.calls[0][0];\n  expect(toolEnd.outputs).toEqual({ result: 'a.txt\\nb.txt' });\n  expect(tool[0].setStatus).not.toHaveBeenCalled();\n\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.session']).toBe('session-xyz');\n  expect(mockTraceInfo.traceMetadata['mlflow.trace.user']).toBeDefined();\n  expect(flushTraces).toHaveBeenCalled();\n});\n\ntest('cancelled tool sets ERROR', async () => {\n  const recs = transcript();\n  recs[2].toolCallResult = { callId: 'c1', status: 'cancelled' };\n  const path = '/tmp/qwen-scratch2.jsonl';\n  writeFileSync(path, recs.map((r) => JSON.stringify(r)).join('\\n'));\n  await processTranscript(path, 's');\n  const tool = byType('TOOL')[0];\n  expect(tool.statusCode).toBe('STATUS_CODE_ERROR');\n  expect(tool.statusMessage).toContain('cancelled');\n});\n"],"version":3}
