`\n * - system records with a message → `{ role: 'system', content }`;\n *   system records without a message are skipped.\n */\nexport function reconstructMessages(records: ChatRecord[], targetIndex: number): OpenAIMessage[] {\n  const messages: OpenAIMessage[] = [];\n\n  for (let i = 0; i < targetIndex; i++) {\n    const record = records[i];\n\n    switch (record.type) {\n      case 'user': {\n        messages.push({ role: 'user', content: getMessageText(record) });\n        break;\n      }\n      case 'assistant': {\n        const functionCalls = getFunctionCalls(record);\n        if (functionCalls.length > 0) {\n          messages.push({\n            role: 'assistant',\n            content: null,\n            tool_calls: functionCalls.map((call) => ({\n              id: call.id,\n              type: 'function',\n              function: {\n                name: call.name,\n                arguments: JSON.stringify(call.args ?? {}),\n              },\n            })),\n          });\n        } else {\n          messages.push({ role: 'assistant', content: getMessageText(record) });\n        }\n        break;\n      }\n      case 'tool_result': {\n        messages.push({\n          role: 'tool',\n          tool_call_id: record.toolCallResult?.callId ?? '',\n          content: getToolOutput(record),\n        });\n        break;\n      }\n      case 'system': {\n        if (record.message) {\n          messages.push({ role: 'system', content: getMessageText(record) });\n        }\n        break;\n      }\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Read a Qwen Code JSONL transcript and convert it into an MLflow trace.\n *\n * When `transcriptPath` is null, returns immediately without creating spans or\n * flushing. Otherwise creates the root AGENT span, per-assistant LLM spans, and\n * per-functionCall TOOL spans, then flushes.\n */\nexport async function processTranscript(\n  transcriptPath: string | null,\n  sessionId?: string,\n): Promise<void> {\n  if (transcriptPath == null) {\n    return;\n  }\n\n  const records = readTranscript(transcriptPath);\n  const toolResults = buildToolResultMap(records);\n\n  const assistantRecords = records.filter((r) => r.type === 'assistant');\n  const firstUser = records.find((r) => r.type === 'user');\n  const lastAssistant = assistantRecords[assistantRecords.length - 1];\n\n  const rootStartNs = firstUser ? parseTimestampToNs(firstUser.timestamp) : null;\n  const rootEndNs = lastAssistant ? parseTimestampToNs(lastAssistant.timestamp) : null;\n\n  // Root span input is the raw user prompt string; output is the final\n  // assistant text. Passing raw strings lets MLflow auto-render the request /\n  // response previews and the session view.\n  const rootSpan = startSpan({\n    name: 'qwen_code_conversation',\n    spanType: SpanType.AGENT,\n    inputs: firstUser ? getMessageText(firstUser) : '',\n    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),\n  });\n\n  for (let i = 0; i < records.length; i++) {\n    const record = records[i];\n    if (record.type !== 'assistant') {\n      continue;\n    }\n\n    const recordNs = parseTimestampToNs(record.timestamp);\n    // The LLM span covers \"thinking\": from the previous record to this one.\n    const prevNs = i > 0 ? parseTimestampToNs(records[i - 1].timestamp) : recordNs;\n    const model = record.model ?? 'unknown';\n\n    const llmSpan = startSpan({\n      name: 'llm_call',\n      parent: rootSpan,\n      spanType: SpanType.LLM,\n      ...(prevNs != null ? { startTimeNs: prevNs } : {}),\n      inputs: {\n        model,\n        messages: reconstructMessages(records, i),\n      },\n      attributes: { model },\n    });\n\n    if (record.usageMetadata) {\n      llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n        [TokenUsageKey.INPUT_TOKENS]: record.usageMetadata.promptTokenCount,\n        [TokenUsageKey.OUTPUT_TOKENS]: record.usageMetadata.candidatesTokenCount,\n        [TokenUsageKey.TOTAL_TOKENS]: record.usageMetadata.totalTokenCount,\n      });\n    }\n\n    llmSpan.end({\n      outputs: {\n        choices: [{ message: { role: 'assistant', content: getMessageText(record) } }],\n      },\n      ...(recordNs != null ? { endTimeNs: recordNs } : {}),\n    });\n\n    // One TOOL span per functionCall part, bracketed by this assistant record\n    // and the matching tool_result record.\n    for (const call of getFunctionCalls(record)) {\n      const toolResult = toolResults.get(call.id);\n      const toolEndNs = toolResult ? parseTimestampToNs(toolResult.timestamp) : recordNs;\n\n      const toolSpan = startSpan({\n        name: `tool_${call.name}`,\n        parent: rootSpan,\n        spanType: SpanType.TOOL,\n        ...(recordNs != null ? { startTimeNs: recordNs } : {}),\n        inputs: call.args ?? {},\n        attributes: { tool_name: call.name, tool_id: call.id },\n      });\n\n      // A cancelled tool call is surfaced as an ERROR span; successful calls\n      // are left in the default (OK) state.\n      if (toolResult?.toolCallResult?.status === 'cancelled') {\n        toolSpan.setStatus(SpanStatusCode.ERROR, `Tool call ${call.name} was cancelled`);\n      }\n\n      toolSpan.end({\n        outputs: { result: toolResult ? getToolOutput(toolResult) : '' },\n        ...(toolEndNs != null ? { endTimeNs: toolEndNs } : {}),\n      });\n    }\n  }\n\n  // Root token usage: input is the LAST assistant call's prompt tokens (the\n  // full accumulated context), output is the sum of generated tokens.\n  const outputTokens = assistantRecords.reduce(\n    (sum, r) => sum + (r.usageMetadata?.candidatesTokenCount ?? 0),\n    0,\n  );\n  const inputTokens = lastAssistant?.usageMetadata?.promptTokenCount ?? 0;\n  rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {\n    [TokenUsageKey.INPUT_TOKENS]: inputTokens,\n    [TokenUsageKey.OUTPUT_TOKENS]: outputTokens,\n    [TokenUsageKey.TOTAL_TOKENS]: inputTokens + outputTokens,\n  });\n\n  // Attach session/user metadata via InMemoryTraceManager, since these traces\n  // are built with startSpan() outside an active OTel context.\n  const traceId = rootSpan.traceId;\n  if (traceId) {\n    const traceManager = InMemoryTraceManager.getInstance();\n    const trace = traceManager.getTrace(traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: sessionId ?? firstUser?.sessionId ?? records[0]?.sessionId ?? '',\n        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',\n      };\n    }\n  }\n\n  rootSpan.end({\n    outputs: lastAssistant ? getMessageText(lastAssistant) : '',\n    ...(rootEndNs != null ? { endTimeNs: rootEndNs } : {}),\n  });\n\n  await flushTraces();\n}\n\n// Re-exported so the tracing module remains the entry point for span-building\n// even when only the LiveSpan type is needed by consumers.\nexport type { LiveSpan };\n"],"version":3}
